package com.hirain.aiagent.rag.policy;
import com.hirain.aiagent.rag.model.*;import java.util.*;
/** 丢弃 normalizedQuery、分数、排名、内部 ID 与诊断，仅映射模型作答所需字段。 */
public final class VehicleKnowledgeToolResultMapper { public VehicleKnowledgeToolResult map(RagResult result,EvidenceIdAllocator ids){List<VehicleKnowledgeEvidence> evidence=new ArrayList<>();if(result.answerable())for(RetrievalEvidence item:result.retrievalEvidence())evidence.add(new VehicleKnowledgeEvidence(ids.nextId(),item.content(),item.documentTitle(),item.documentVersion(),item.sourceLocator(),item.applicability()));return result(result,evidence);} public VehicleKnowledgeToolResult map(RagResult result,KnowledgeRequestState state){List<VehicleKnowledgeEvidence> evidence=new ArrayList<>();if(result.answerable())for(RetrievalEvidence item:result.retrievalEvidence())evidence.add(new VehicleKnowledgeEvidence(state.evidenceIdFor(item),item.content(),item.documentTitle(),item.documentVersion(),item.sourceLocator(),item.applicability()));return result(result,evidence);}private static VehicleKnowledgeToolResult result(RagResult result,List<VehicleKnowledgeEvidence> evidence){return new VehicleKnowledgeToolResult(result.schemaVersion(),result.status(),result.answerable(),result.query(),evidence,result.degradedReasons(),result.failureReasonCode(),result.answerable()?"已找到车辆资料依据。":"未找到可确认的车辆资料依据。");} }
